//! Integration test for the first real HSAI-owned Phala/dstack artifact.
//!
//! This fixture was generated by deploying a real tdx.small CVM on Phala Cloud,
//! injecting the HSAI-owned fresh challenge's `expected_report_data_hex` into the
//! dstack `reportData` field via `getQuote`, and capturing the non-secret
//! artifact bundle. It is local regression evidence that the HSAI binding
//! mechanism works against real TDX hardware. It is not proof, not benchmark
//! evidence, not backend execution evidence, and not broader Phase 4 evidence
//! beyond the bounded anchor-registry start condition.
//!
//! The agent keypair is a real P-256 key generated for this capture. The private
//! key is not in the repo. Hardware authenticity is managed-verifier only;
//! signature/JWKS/JWT/DCAP verification remains out of scope.

use hsai_agent_case::EvidenceLane;
use hsai_agent_case::{ActionId, AgentCase, MemoryRoot, ModelId, OracleContract, Verdict};
use hsai_attestation_phala::{
    parse_phala_artifact, validate_phala_artifact, PhalaArtifactAttestationLane,
    PhalaArtifactBundle, PhalaValidationPolicy,
};
use hsai_claim_envelope::{
    admits, conjoin, AcceptancePolicy, Maturity, Predicate, PropertyKind, SubjectId, TrustRootClass,
};
use hsai_distinct_agent::{distinctness, Anchor, AnchorBundle, DistinctAgentLane};
use std::collections::BTreeSet;

const FIXTURE: &str = include_str!("fixtures/phala_hsai_owned_real_2026_06_16.json");

fn bundle() -> PhalaArtifactBundle {
    parse_phala_artifact(FIXTURE).expect("real HSAI-owned fixture must parse")
}

fn anchor(bundle: &PhalaArtifactBundle) -> Anchor {
    Anchor::HardwareAttested {
        vendor: "phala-dstack".to_owned(),
        device: bundle.app_id.clone(),
    }
}

fn subject(id: &str) -> SubjectId {
    SubjectId(id.to_owned())
}

fn semantic_correctness_action1() -> Predicate {
    Predicate {
        subject: subject("action1"),
        property: PropertyKind::SemanticCorrectness,
    }
}

fn case(bundle: &PhalaArtifactBundle) -> AgentCase {
    AgentCase {
        action: ActionId("action1".to_owned()),
        subject: subject("hsai-capture-agent-2026-06-16"),
        claimed_model: ModelId("hsai-capture-emitter-2026-06-16".to_owned()),
        memory_root: MemoryRoot([7; 32]),
        observed_at: bundle.observed_timestamp,
        oracle: OracleContract {
            expected: Verdict::Accept,
            target_guarantees: BTreeSet::from([distinctness(&subject(
                "hsai-capture-agent-2026-06-16",
            ))]),
            excluded: BTreeSet::from([semantic_correctness_action1()]),
        },
    }
}

fn acceptance_policy(case: &AgentCase) -> AcceptancePolicy {
    AcceptancePolicy {
        require: BTreeSet::from([distinctness(&case.subject)]),
        min_maturity: Maturity::Attested,
        forbid_roots: BTreeSet::<TrustRootClass>::new(),
        require_closed: true,
        at: case.observed_at,
    }
}

fn mutate_first_hex_char(value: &mut String) {
    let replacement = if value.starts_with('0') { "1" } else { "0" };
    value.replace_range(0..1, replacement);
}

#[test]
fn real_hsai_owned_artifact_requires_authenticated_quote_backend() {
    let bundle = bundle();
    let policy = PhalaValidationPolicy::for_bundle(&bundle, 600);
    assert!(matches!(
        validate_phala_artifact(&bundle, &policy, bundle.observed_timestamp),
        Err(hsai_attestation_phala::PhalaValidationError::QuoteUnverified)
    ));
}

#[test]
fn real_artifact_report_data_binding_is_recomputable() {
    let bundle = bundle();
    let policy = PhalaValidationPolicy::for_bundle(&bundle, 600);

    // The validator recomputes the local report-data binding, but does not
    // authorize the artifact until a quote backend authenticates the quote.
    assert!(matches!(
        validate_phala_artifact(&bundle, &policy, bundle.observed_timestamp),
        Err(hsai_attestation_phala::PhalaValidationError::QuoteUnverified)
    ));

    // Tampering the report data must break the binding.
    let mut tampered = bundle.clone();
    mutate_first_hex_char(&mut tampered.report_data_hex);
    let tampered_policy = PhalaValidationPolicy {
        expected_report_data_hex: tampered.report_data_hex.clone(),
        ..PhalaValidationPolicy::for_bundle(&bundle, 600)
    };
    assert!(
        validate_phala_artifact(&tampered, &tampered_policy, bundle.observed_timestamp).is_err()
    );
}

#[test]
fn real_artifact_closes_distinctness_at_attested_maturity() {
    let bundle = bundle();
    let policy = PhalaValidationPolicy::for_bundle(&bundle, 600);
    let case = case(&bundle);
    let anchor = anchor(&bundle);
    let distinct =
        DistinctAgentLane::new(AnchorBundle(BTreeSet::from([anchor.clone()]))).evaluate(&case);
    let attestation = PhalaArtifactAttestationLane::new(anchor, bundle, policy).evaluate(&case);
    let combined = conjoin(distinct, attestation);

    assert_eq!(combined.maturity, Maturity::Stub);
    assert!(!combined.assumptions.is_empty());
    assert!(admits(acceptance_policy(&case), combined).is_err());
}

#[test]
fn real_artifact_managed_verifier_trust_roots_are_visible() {
    let bundle = bundle();
    let policy = PhalaValidationPolicy::for_bundle(&bundle, 600);
    assert!(matches!(
        validate_phala_artifact(&bundle, &policy, bundle.observed_timestamp),
        Err(hsai_attestation_phala::PhalaValidationError::QuoteUnverified)
    ));
}

#[test]
fn real_artifact_phase3_format_also_requires_authenticated_quote_backend() {
    let phase3_fixture = include_str!("fixtures/phala_trust_center_app_2026_06_16.json");
    let bundle = parse_phala_artifact(phase3_fixture).expect("Phase 3 fixture must parse");
    let policy = PhalaValidationPolicy::for_bundle(&bundle, 600);
    assert!(matches!(
        validate_phala_artifact(&bundle, &policy, bundle.observed_timestamp),
        Err(hsai_attestation_phala::PhalaValidationError::QuoteUnverified)
    ));
}
